import{_ as a,o as i,c as s,al as o}from"./chunks/framework.7vp1BMOE.js";const h=JSON.parse('{"title":"MAVLink Profiles","description":"","frontmatter":{},"headers":[],"relativePath":"uk/mavlink/mavlink_profiles.md","filePath":"uk/mavlink/mavlink_profiles.md"}'),t={name:"uk/mavlink/mavlink_profiles.md"};function n(r,e,l,c,d,m){return i(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="mavlink-profiles" tabindex="-1">MAVLink Profiles <a class="header-anchor" href="#mavlink-profiles" aria-label="Permalink to &quot;MAVLink Profiles&quot;">​</a></h1><p>A MAVLink <em>profile</em> (also called a <em>mode</em>) defines a set of messages that can be streamed by default on a MAVLink channel and their rates.</p><p>This section lists the profiles, and explains how they can be used and extended.</p><h2 id="available-profiles" tabindex="-1">Available Profiles <a class="header-anchor" href="#available-profiles" aria-label="Permalink to &quot;Available Profiles&quot;">​</a></h2><p>The available profiles (in source-code declaration order) are:</p><ul><li><em>Normal</em> (<code>MAVLINK_MODE_NORMAL</code>): Set of messages for a GCS.</li><li><em>Onboard</em> (<code>MAVLINK_MODE_ONBOARD</code>): Set of messages for a companion computer on a fast link (such as Ethernet).</li><li><em>Gimbal</em> (<code>MAVLINK_MODE_GIMBAL</code>): Messages for a gimbal. Note this also enables message forwarding.</li><li><em>External Vision</em> (<code>MAVLINK_MODE_EXTVISION</code>): Messages for offboard vision systems.</li><li><em>External Vision Minimal</em> (<code>MAVLINK_MODE_EXTVISIONMIN</code>): Messages for offboard vision systems on slower links.</li><li><em>OSD</em> (<code>MAVLINK_MODE_OSD</code>): Set of messages for an <a href="./../peripherals/osd#mavlink-osd">On-Screen Display (OSD)</a> system.</li><li><em>Magic</em> (<code>MAVLINK_MODE_MAGIC</code>): No messages streamed by default. Used when configuring streaming dynamically via MAVLink.</li><li><em>Custom</em> (<code>MAVLINK_MODE_CUSTOM</code>): Same as <code>MAVLINK_MODE_MAGIC</code>.</li><li><em>Config</em> (<code>MAVLINK_MODE_CONFIG</code>): Set of messages for configuration interface, sent at higher rates. This is used, for example, to send the <code>MAVLINK_MODE_NORMAL</code> message set via USB to a GCS.</li><li><em>Iridium</em> (<code>MAVLINK_MODE_IRIDIUM</code>): Streams <code>HIGH_LATENCY2</code> message to an iridium satellite phone.</li><li><em>Minimal</em> (<code>MAVLINK_MODE_MINIMAL</code>): Minimal set of messages for use with a GCS on a poor telemetry link.</li><li><em>Onboard Low Bandwidth</em> (<code>MAVLINK_MODE_ONBOARD_LOW_BANDWIDTH</code>): Set of messages to be streamed to a companion computer for re-routing to a reduced-traffic link, such as a GCS.</li><li><em>Low Bandwidth</em> (<code>MAVLINK_MODE_LOW_BANDWIDTH</code>): Reduced message set for low bandwidth links.</li><li><em>uAvionix</em> (<code>MAVLINK_MODE_UAVIONIX</code>): Messages for a uAvionix ADS-B beacon.</li><li><em>Distance Sensor</em> (<code>MAVLINK_MODE_DISTANCE_SENSOR</code>): Streams distance sensor data at unlimited rate.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The profile defines the <em>default</em> messages and rates. A connected MAVLink system can still request the streams/rates it wants using <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_SET_MESSAGE_INTERVAL" target="_blank" rel="noreferrer">MAV_CMD_SET_MESSAGE_INTERVAL</a>.</p></div><p>To find the exact messages in each profile, search for <code>configure_streams_to_default</code> (or the above profile names) in <a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/modules/mavlink/mavlink_main.cpp" target="_blank" rel="noreferrer">mavlink_main.cpp</a>.</p><h2 id="assigning-profiles-to-ports" tabindex="-1">Assigning Profiles to Ports <a class="header-anchor" href="#assigning-profiles-to-ports" aria-label="Permalink to &quot;Assigning Profiles to Ports&quot;">​</a></h2><p><a href="./../peripherals/mavlink_peripherals">MAVLink Peripherals</a> explains how to set up a port for communicating over MAVLink. This uses the concept of an abstract <a href="./../peripherals/mavlink_peripherals#mavlink-instances">MAVLink instance</a> which is then assigned to a serial port.</p><p>The profile associated with a particular MAVLink instance is set using the associated <code>MAV_X_MODE</code> parameter:</p><ul><li><a href="./../advanced_config/parameter_reference#MAV_0_MODE">MAV_0_MODE</a></li><li><a href="./../advanced_config/parameter_reference#MAV_1_MODE">MAV_1_MODE</a></li><li><a href="./../advanced_config/parameter_reference#MAV_2_MODE">MAV_2_MODE</a></li></ul><p>There are also dedicated profile parameters for ports that are not configured via MAVLink instances:</p><ul><li><a href="./../advanced_config/parameter_reference#USB_MAV_MODE">USB_MAV_MODE</a>: Profile for the USB port (used when MAVLink is set or detected on USB).</li><li><a href="./../advanced_config/parameter_reference#MAV_S_MODE">MAV_S_MODE</a>: Profile for the internal SOM (System on Module) to FMU communication channel, used on boards where the FMU and companion computer are co-located on the same module.</li></ul><p>Note that not all profiles can necessarily be set on these ports.</p><h2 id="adding-messages-to-a-profile" tabindex="-1">Adding Messages to a Profile <a class="header-anchor" href="#adding-messages-to-a-profile" aria-label="Permalink to &quot;Adding Messages to a Profile&quot;">​</a></h2><p>You can add messages to a profile in appropriate <code>case</code> switch in the <a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/modules/mavlink/mavlink_main.cpp#L1430" target="_blank" rel="noreferrer">Mavlink::configure_streams_to_default(const char *configure_single_stream)</a> method (see <a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/modules/mavlink/mavlink_main.cpp" target="_blank" rel="noreferrer">mavlink_main.cpp</a>).</p><p>If you&#39;re testing with a GCS over USB you might add the message to the <code>MAVLINK_MODE_CONFIG</code> case using the <code>configure_stream_local()</code> method. For example, to stream <code>BATTERY_STATUS_DEMO</code> at 5 Hz:</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">	case</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MAVLINK_MODE_CONFIG:</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // USB</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">		// Note: streams requiring low latency come first</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">		...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">		configure_stream_local</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;BATTERY_STATUS_DEMO&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5.0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        ...</span></span></code></pre></div><p>See <a href="./streaming_messages">Streaming MAVLink Messages</a> for a more detailed example.</p>`,20)])])}const _=a(t,[["render",n]]);export{h as __pageData,_ as default};
